    "The portal rings repeatedly while open. Background requests arrive as phone or laptop notifications.": "போர்டல் திறந்திருக்கும் போது மீண்டும் மீண்டும் ஒலிக்கிறது. பின்னணி கோரிக்கைகள் ஃபோன் அல்லது லேப்டாப் அறிவிப்புகளாக வரும்.",
    "The request has been removed from your active work.": "உங்கள் செயலில் உள்ள பணியிலிருந்து கோரிக்கை அகற்றப்பட்டது.",
    "The verification team will review your identity, documents, references, knowledge and payout information. Please recheck later.": "சரிபார்ப்புக் குழு உங்கள் அடையாளம், ஆவணங்கள், குறிப்புகள், அறிவு மற்றும் பணம் செலுத்தும் தகவலை மதிப்பாய்வு செய்யும். தயவுசெய்து பின்னர் மீண்டும் சரிபார்க்கவும்.",
    "These requests were cancelled by the customer and no longer need action.": "இந்த கோரிக்கைகள் வாடிக்கையாளரால் ரத்து செய்யப்பட்டன, இனி நடவடிக்கை தேவையில்லை.",
    "This browser cannot play the request alarm.": "இந்த உலாவி கோரிக்கை அலாரத்தை இயக்க முடியாது.",
    "This consultation has ended": "இந்த ஆலோசனை முடிந்தது",
    "This page checks for updates automatically every few seconds.": "இந்தப் பக்கம் ஒவ்வொரு சில வினாடிகளுக்கும் தானாகவே புதுப்பிப்புகளைச் சரிபார்க்கிறது.",
    "Today&apos;s work": "இன்றைய வேலை",
    "Travel compensation pending: ₹": "பயண இழப்பீடு நிலுவையில் உள்ளது: ₹",
